`timescale 1ns/1ps
// -----------------------------------------------------------------------------
// tb_top.sv : top-level UVM testbench
//   1. clock           2. the physical interface        3. the DUT
//   4. hand the interface to UVM through config_db, then run_test()
// The default test is mlp_iris_test; +UVM_TESTNAME=<test> overrides it.
// -----------------------------------------------------------------------------
module tb_top;
  import uvm_pkg::*;
  import mlp_pkg::*;

  // 1. Clock (reset is generated by the driver, as in the lab guide)
  logic clk = 1'b0;
  always #5 clk = ~clk;                         // 100 MHz

  // 2. Physical interface
  mlp_if vif (clk);

  // 3. DUT
  mlp_layer dut (
    .clk       (clk),
    .rst_n     (vif.rst_n),
    .wr_en     (vif.wr_en),
    .wr_addr   (vif.wr_addr),
    .wr_data   (vif.wr_data),
    .in_valid  (vif.in_valid),
    .in_ready  (vif.in_ready),
    .in_data   (vif.in_data),
    .out_valid (vif.out_valid),
    .out_ready (vif.out_ready),
    .out_data  (vif.out_data),
    .busy      (vif.busy)
  );

  // State probe: which pipeline registers hold a sample (used by the reset test)
  assign vif.dbg_stage = {dut.s1_valid, dut.out_valid};

  // MON=1 : text trace of the pins, one entry whenever any pin changes
  integer      mon_fd  = 0;
  bit          mon_en  = 1'b0;
  longint unsigned cyc = 0;
  logic [127:0] prev_snap = '1;
  initial begin
    string tn;
    mon_en = $test$plusargs("MON");
    if (mon_en) begin
      if (!$value$plusargs("UVM_TESTNAME=%s", tn)) tn = "mlp_iris_test";
      mon_fd = $fopen({tn, "_pins.log"}, "w");
    end
  end
  always @(posedge clk) begin
    logic [127:0] snap;
    cyc++;
    snap = {vif.rst_n, vif.wr_en, vif.wr_addr, vif.wr_data, vif.in_valid, vif.in_ready,
            vif.in_data, vif.out_valid, vif.out_ready, vif.out_data, vif.busy};
    if (mon_en && snap !== prev_snap) begin
      $fdisplay(mon_fd, "cycle %0d  (%0t)", cyc, $time);
      $fdisplay(mon_fd, "   in : rst_n=%b wr_en=%b wr_addr=%0d wr_data=%0d in_valid=%b in_data=%h out_ready=%b",
                vif.rst_n, vif.wr_en, vif.wr_addr, vif.wr_data, vif.in_valid, vif.in_data, vif.out_ready);
      $fdisplay(mon_fd, "   out: in_ready=%b out_valid=%b out_data=%h busy=%b   (buses in hex)",
                vif.in_ready, vif.out_valid, vif.out_data, vif.busy);
      prev_snap = snap;
    end
  end

  // Waves: +VPD (VCS .vpd, other simulators fall back to .vcd), +FSDB (Verdi, if compiled with +define+FSDB)
  initial begin
    if ($test$plusargs("VPD")) begin
`ifdef VCS
      $vcdplusfile("mlp.vpd");
      $vcdpluson(0, tb_top);
`else
      $dumpfile("mlp.vcd");
      $dumpvars(0, tb_top);
`endif
    end
`ifdef FSDB
    if ($test$plusargs("FSDB")) begin
      $fsdbDumpfile("mlp.fsdb");
      $fsdbDumpvars(0, tb_top);
    end
`endif
  end

  // 4. Start UVM.  The default test is mlp_iris_test.  +UVM_TESTNAME=<test> overrides it;
  //    it is read here with $value$plusargs so it also works on simulators whose UVM is
  //    built without its C (DPI) command-line code.
  initial begin
    string tname = "mlp_iris_test";
    void'($value$plusargs("UVM_TESTNAME=%s", tname));
    uvm_config_db#(virtual mlp_if)::set(null, "*", "vif", vif);
    run_test(tname);
  end
endmodule
